## Direct SPIR-V: a source local named like a generated byref temporary
## Test that generated by-ref temporary names cannot collide with source locals
##
## Run:
##   nim c -r --hints:off --warnings:off \
##     --outdir:build/tests --nimcache:nimcache/tests \
##     workspace/crucible/tests/codegen/vulkan_via_spirv/app/t_spirv_byref_temp_name.nim

import std/[os, osproc]
import workspace/crucible

type
  Count = object
    n: int32
    pad: array[16, int32]

const byrefTmpCollisionSpv = spirv:
  proc readCount(c: Count): int32 {.device.} =
    c.n + 1'i32

  proc tempNameKernel(output: ptr UncheckedArray[int32]) {.global.} =
    var byref_tmp1: int32 = 111'i32
    # Non-lvalue constructor result: by-ref lowering hoists a temporary for it.
    output[0] = readCount(Count(n: 41'i32))
    # A source local named like the generated temporary survives the call.
    output[1] = byref_tmp1

proc runTest() =
  let spirvVal = findExe("spirv-val")
  doAssert spirvVal.len > 0,
    "spirv-val not found on PATH, install the SPIRV-Tools (brew install spirv-tools)"
  let outDir = "build/tests"
  createDir(outDir)
  let spvPath = outDir / "t_spirv_byref_temp_name.spv"
  block:
    var f = open(spvPath, fmWrite)
    defer: f.close()
    discard f.writeBuffer(addr byrefTmpCollisionSpv[0], byrefTmpCollisionSpv.len * 4)
  let (valOut, valCode) = execCmdEx(spirvVal & " --target-env vulkan1.4 " & spvPath)
  doAssert valCode == 0, "spirv-val rejected the executed module:\n" & valOut

  var engine = newEngine(runVulkan)
  engine.ingest(byrefTmpCollisionSpv)
  let oDev = engine.allocDevice(int32, 2)
  var zeros: array[2, int32]
  engine.copyToDeviceFromHost(oDev, zeros)

  engine.launchKernel("tempNameKernel", oDev, ())
  var got: array[2, int32]
  engine.copyToHostFromDevice(got.toOpenArray(0, 1), oDev)
  doAssert got[0] == 42'i32,
    "the by-ref call computes from its hoisted temporary, got " & $got[0]
  doAssert got[1] == 111'i32,
    "the source local keeps its value after the by-ref call, got " & $got[1]
  echo "[OK] direct SPIR-V: by-ref temporary names cannot collide with source locals"

when isMainModule:
  runTest()
  echo "t_spirv_byref_temp_name: all checks passed"
